#### 1. JavaScript Function

```javascript
// Function to check if the user is logged in
function checkUserAuthentication() {
  // Assuming you have a function to get the current user session
  const userSession = getUserSession();

  // If the user session is not found or the user is not logged in
  if (!userSession || !userSession.isLoggedIn) {
    // Redirect to the login page
    window.location.href = '/login';
  } else {
    // User is logged in, proceed with the current page
    console.log('User is logged in. Proceeding with the page.');
  }
}

// Call the function when the page loads
window.onload = checkUserAuthentication;
